import React, { useMemo } from 'react';
import { Alert, Box, Button, Typography } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import { ProfileCompletenessCard } from './shared/ProfileCompletenessCard';
import { DashboardNextBestAction } from './dashboard/DashboardNextBestAction';
import { computeMsmeProfileCompleteness, deriveNextBestAction } from '../utils/sustainabilityUx';
import { useMsmeSetupProgress } from '../hooks/useMsmeSetupProgress';
import { useMsmeProfileQuery } from '../hooks/queries/useMsmeWorkspaceQueries';
import { MSME_SIMPLIFIED_SECTION_TITLE } from '../constants/msmeSimplifiedUi';

const OperationsPage: React.FC = () => {
  const location = useLocation();
  const profileQuery = useMsmeProfileQuery();
  const setupProgress = useMsmeSetupProgress();

  const profile = (profileQuery.data as { data?: Record<string, unknown> } | undefined)?.data
    ?? (profileQuery.data as Record<string, unknown> | undefined)
    ?? null;

  const fromLocation = (location.state as { from?: { pathname?: string } } | null)?.from;
  const fromPath = fromLocation?.pathname;
  const showWorkflowGateHint =
    Boolean(fromPath) &&
    fromPath !== '/operations' &&
    !fromPath?.startsWith('/msme-profile');

  const profileCompleteness = useMemo(
    () => computeMsmeProfileCompleteness(profile),
    [profile]
  );

  const profileComplete = setupProgress.progress.steps.find((step) => step.id === 'profile')?.complete ?? false;
  const hasDocuments = setupProgress.progress.steps.find((step) => step.id === 'documents')?.complete ?? false;
  const hasAssessment = setupProgress.progress.steps.find((step) => step.id === 'assessment')?.complete ?? false;
  const hasWorkflow = setupProgress.progress.steps.find((step) => step.id === 'operations')?.complete ?? false;

  const nextAction = useMemo(
    () =>
      deriveNextBestAction({
        hasProfile: profileComplete,
        hasDocuments,
        hasAssessment,
        hasWorkflow,
        carbonScore: 0,
      }),
    [profileComplete, hasDocuments, hasAssessment, hasWorkflow]
  );

  const onboardingNextStep = setupProgress.nextStep;
  const setupInProgress = !setupProgress.loading && !setupProgress.progress.allComplete;

  return (
    <Box>
      {showWorkflowGateHint && (
        <Alert severity="info" sx={{ mb: 2 }}>
          Complete the operations workflow below to unlock the rest of the app (for example{' '}
          {fromPath === '/dashboard' ? 'the dashboard' : `“${fromPath}”`}). You can return there when the planner is
          finished.
        </Alert>
      )}

      {setupInProgress && onboardingNextStep ? (
        <Alert severity="info" sx={{ mb: 2 }}>
          {MSME_SIMPLIFIED_SECTION_TITLE}: {setupProgress.progress.completedCount} of{' '}
          {setupProgress.progress.totalCount} steps done.{' '}
          {onboardingNextStep.id === 'operations'
            ? 'You are on the final step — map units and activity drivers below.'
            : `Next up: ${onboardingNextStep.label.toLowerCase()}.`}
          {onboardingNextStep.id !== 'operations' ? (
            <Button
              component={RouterLink}
              to={onboardingNextStep.path}
              size="small"
              sx={{ ml: 1, verticalAlign: 'baseline' }}
            >
              Go to step
            </Button>
          ) : null}
        </Alert>
      ) : null}

      <Typography variant="body1" color="text.secondary" sx={{ mb: 2, maxWidth: 900 }}>
        Work through each section in order: add your units, then Scope 1–3 activity data, and save on Review.
        Listed-company and GHG organizational boundary fields live on{' '}
        <Button component={RouterLink} to="/msme-profile" size="small" sx={{ px: 0.5, minWidth: 0, verticalAlign: 'baseline' }}>
          Profile
        </Button>
        {' '}when you need them for BRSR filing.
      </Typography>

      {profile && (
        <>
          <ProfileCompletenessCard
            result={profileCompleteness}
            title="Company profile completeness"
            actionPath="/msme-registration"
            actionLabel="Edit company profile"
          />
          {setupInProgress && nextAction.path !== '/operations' ? (
            <DashboardNextBestAction action={nextAction} />
          ) : null}
        </>
      )}

      <ManufacturingWorkflowPlanner isEmbeddedInOperationsPage />
    </Box>
  );
};

export default OperationsPage;
